<script setup lang="ts">
import {onBeforeUnmount,onMounted,ref} from 'vue';
import AppDialog from './AppDialog.vue';

type SmtpView={ativo:boolean;host:string;porta:number;secure:boolean;usuario:string;remetente:string;temSenha:boolean;versao:number};
const props=defineProps<{request:<T>(path:string,method?:string,body?:unknown,signal?:AbortSignal)=>Promise<T>}>();
const config=ref<SmtpView|null>(null),loading=ref(false),loaded=ref(false),error=ref(''),notice=ref(''),editing=ref(false),saving=ref(false),formError=ref('');
const ativo=ref(false),host=ref(''),porta=ref(587),secure=ref(false),usuario=ref(''),remetente=ref(''),senha=ref(''),limparSenha=ref(false);
let alive=true;
function message(cause:unknown){return (cause as Error)?.message||'Não foi possível concluir a operação.';}
function fill(value:SmtpView){ativo.value=value.ativo;host.value=value.host;porta.value=value.porta;secure.value=value.secure;usuario.value=value.usuario;remetente.value=value.remetente;senha.value='';limparSenha.value=false;}
async function load(){if(loading.value)return;loading.value=true;error.value='';try{const value=await props.request<SmtpView>('/api/contexto/smtp');if(!alive)return;config.value=value;loaded.value=true;if(!editing.value)fill(value);}catch(cause){if(alive)error.value=message(cause);}finally{if(alive)loading.value=false;}}
function open(){if(!config.value)return;fill(config.value);notice.value='';formError.value='';editing.value=true;}
function close(){if(!saving.value)editing.value=false;}
function validEmail(value:string){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);}
async function save(){if(saving.value)return;formError.value='';const normalizedHost=host.value.trim(),normalizedUser=usuario.value.trim(),normalizedFrom=remetente.value.trim().toLowerCase(),normalizedPort=Number(porta.value);if(ativo.value&&!normalizedHost){formError.value='Informe o servidor SMTP antes de ativar o canal.';return;}if(!Number.isInteger(normalizedPort)||normalizedPort<1||normalizedPort>65535){formError.value='Informe uma porta SMTP entre 1 e 65535.';return;}if(ativo.value&&!validEmail(normalizedFrom)){formError.value='Informe um remetente de e-mail válido.';return;}if(normalizedUser&&!senha.value&&!config.value?.temSenha&&!limparSenha.value){formError.value='Informe a senha SMTP do usuário configurado.';return;}const payload:{ativo:boolean;host:string;porta:number;secure:boolean;usuario:string;remetente:string;senha?:string;limparSenha?:boolean}={ativo:ativo.value,host:normalizedHost,porta:normalizedPort,secure:secure.value,usuario:normalizedUser,remetente:normalizedFrom};if(senha.value)payload.senha=senha.value;else if(limparSenha.value)payload.limparSenha=true;saving.value=true;try{const value=await props.request<SmtpView>('/api/contexto/smtp','PUT',payload);if(!alive)return;config.value=value;fill(value);notice.value='Canais salvos.';editing.value=true;}catch(cause){if(alive)formError.value=message(cause);}finally{if(alive)saving.value=false;}}
onMounted(()=>{void load();});
onBeforeUnmount(()=>{alive=false;});
</script>

<template>
  <section class="smtp-panel" aria-label="Canais e notificações">
    <header class="smtp-heading"><div><span class="eyebrow">Entrega contextual</span><h2>Canais e notificações</h2><p>Configure o canal de e-mail usado pelo escritório. Segredos permanecem protegidos no servidor.</p></div><button type="button" class="primary" :disabled="loading||saving||!config" @click="open">Configurar canais e e-mail</button></header>
    <p v-if="loading" role="status">Consultando canais…</p>
    <div v-if="error" class="smtp-error" role="alert"><p>{{ error }}</p><button type="button" class="secondary" :disabled="loading" @click="load">Tentar novamente</button></div>
    <article v-if="config&&!error" class="smtp-card"><div class="smtp-card-heading"><div><span class="eyebrow">E-mail do escritório</span><h3>{{ config.ativo?'Ativo':'Desativado' }}</h3><p>{{ config.host||'Nenhum servidor SMTP configurado.' }}</p></div><span class="status-badge" :data-tone="config.ativo?'success':'neutral'">{{ config.ativo?'Pronto para uso':'Não configurado' }}</span></div><dl class="smtp-details"><div><dt>Remetente</dt><dd>{{ config.remetente||'Não informado' }}</dd></div><div><dt>Servidor e porta</dt><dd>{{ config.host?`${config.host}:${config.porta}`:'Não informado' }}</dd></div><div><dt>Segurança</dt><dd>{{ config.secure?'TLS':'Sem TLS' }}</dd></div><div><dt>Credencial</dt><dd>{{ config.temSenha?'Senha configurada no servidor':'Senha não configurada' }}</dd></div></dl><p class="smtp-contract">O contrato contextual atual expõe e-mail SMTP. Outros canais e teste de conexão separado não estão disponíveis nesta área.</p></article>
    <AppDialog v-if="editing" title="Canais e e-mail" :busy="saving" @close="close"><p v-if="notice" role="status">{{ notice }}</p><p v-if="formError" role="alert">{{ formError }}</p><p class="smtp-contract">O backend atual não oferece teste de conexão separado.</p><p class="smtp-contract">Salvar a configuração não dispara envio.</p><form class="vue-form smtp-form" :aria-busy="saving" @submit.prevent="save"><label class="smtp-check"><input v-model="ativo" type="checkbox" :disabled="saving">Ativar e-mail do escritório</label><label>Servidor SMTP<input v-model="host" type="text" autocomplete="off" maxlength="500" :disabled="saving"></label><label>Porta SMTP<input v-model.number="porta" type="number" min="1" max="65535" inputmode="numeric" :disabled="saving"></label><label class="smtp-check"><input v-model="secure" type="checkbox" :disabled="saving">Usar conexão segura (TLS)</label><label>Usuário SMTP<input v-model="usuario" type="text" autocomplete="username" maxlength="500" :disabled="saving"></label><label>Remetente<input v-model="remetente" type="email" autocomplete="email" maxlength="998" :disabled="saving"></label><label>Senha SMTP<input v-model="senha" type="password" autocomplete="new-password" maxlength="4000" :disabled="saving" placeholder="Deixe em branco para preservar a senha salva"></label><label v-if="config?.temSenha" class="smtp-check"><input v-model="limparSenha" type="checkbox" :disabled="saving||!!senha">Remover senha salva</label><p v-if="config?.temSenha" class="smtp-secret">Senha configurada no servidor; o valor não é exibido.</p><footer><button type="button" class="secondary" :disabled="saving" @click="close">Cancelar</button><button type="submit" class="primary" :disabled="saving">{{ saving?'Salvando…':'Salvar canais' }}</button></footer></form></AppDialog>
  </section>
</template>

<style scoped>
.smtp-heading,.smtp-card-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.smtp-heading{margin-top:32px}.smtp-heading h2,.smtp-card-heading h3{margin:4px 0 8px}.smtp-heading p,.smtp-card-heading p,.smtp-contract,.smtp-secret{margin:0;color:var(--muted)}.smtp-card{max-width:1000px;margin-top:18px;padding:24px;border:1px solid var(--line);border-radius:var(--radius-card);background:var(--surface)}.smtp-card-heading .status-badge{margin-left:auto}.smtp-details{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:24px 0 0}.smtp-details div{min-width:0;padding:14px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--surface-muted)}.smtp-details dt{font-size:.85rem;color:var(--muted)}.smtp-details dd{margin:6px 0 0;overflow-wrap:anywhere}.smtp-contract{margin-top:18px;font-size:.9rem}.smtp-error{margin-top:20px;padding:14px;border-radius:var(--radius-control);background:color-mix(in srgb,var(--danger) 12%,transparent)}.smtp-error p{margin:0 0 10px}.smtp-form{min-width:min(100%,560px)}.smtp-form footer{display:flex;justify-content:flex-end;gap:12px;margin-top:16px}.smtp-check{display:flex;align-items:center;gap:10px}.smtp-check input{width:auto}.smtp-secret{font-size:.9rem}@media(max-width:700px){.smtp-heading button{width:100%}.smtp-card{padding:16px}.smtp-card-heading .status-badge{margin-left:0}.smtp-details{grid-template-columns:1fr}.smtp-form footer{flex-direction:column}.smtp-form footer button{width:100%}}
</style>
